type Product = { id: number; brand: string; model: string; processor: string; generation: string; ram: string; ramType: string; storage: string; gpu: string; os: string; serial?: string; screen: string; category: "Notebook" | "Desktop"; condition: "Seminovo revisado" | "Novo"; price: string; originalPrice?: string | null; promoPrice?: string | null; imageUrl?: string | null; badge?: string | null; cosmeticCondition?: string | null; battery?: string | null; accessories?: string | null; notes?: string | null; status: "available" | "sold" | "hidden" };
function visible(value: unknown) { const text = String(value ?? "").trim(); return Boolean(text) && !["—", "-", "não informado", "não informada", "a confirmar", "não especificado"].includes(text.toLowerCase()); }
function whatsappFor(product: Product) { const price = product.promoPrice || product.price; return `${WHATSAPP}?text=${encodeURIComponent(`Olá! Tenho interesse no ${product.brand} ${product.model} da C7 Store. Vi o valor de ${price} no catálogo e gostaria de confirmar disponibilidade, garantia e condições de pagamento.`)}`; }
function directProductUrl(product: Product, galleryMode: "all" | "primary" = "all") { if (typeof window === "undefined") return ""; const params = new URLSearchParams({ produto: String(product.id) }); if (galleryMode === "primary") params.set("galeria", "principal"); return `${window.location.origin}${window.location.pathname}?${params.toString()}`; }
async function shareProduct(product: Product) { const url = directProductUrl(product); const text = `Olha este ${product.category.toLowerCase()} seminovo da C7 Store: ${product.brand} ${product.model}.`; if (typeof navigator !== "undefined" && navigator.share) { try { await navigator.share({ title: `${product.brand} ${product.model} · C7 Store`, text, url }); return; } catch (error) { if (error instanceof DOMException && error.name === "AbortError") return; } } window.open(`${WHATSAPP}?text=${encodeURIComponent(`${text}\n${url}`)}`, "_blank", "noopener,noreferrer"); }


function purposeFor(product: Product) { const text = [product.model, product.processor, product.gpu, product.notes, product.accessories].join(" ").toLowerCase(); if (/gaming|jogos|gtx|rtx|radeon|geforce/.test(text)) return "Jogos"; if (/design|criacao|criação|edição|editor|photoshop|video|vídeo/.test(text)) return "Edição/criação"; if (/office|trabalho|empresa|profissional|thinkpad|vostro|inspiron/.test(text)) return "Trabalho"; if (/estudo|escola|aula/.test(text)) return "Estudos"; return "Uso básico"; }
function purposeLabelFor(product: Product) { const purpose = purposeFor(product); return purpose === "Uso básico" ? "Para o dia a dia" : `Para ${purpose.toLowerCase()}`; }
 function shareText(product: Product, url: string, galleryMode: "all" | "primary" = "all") { const galleryLabel = galleryMode === "primary" ? "com a foto principal" : "com todas as fotos"; return `Olá! Confira este ${product.category.toLowerCase()} seminovo da C7 Store: ${product.brand} ${product.model}, ${galleryLabel}. ${product.promoPrice || product.price} · 1 ano de garantia.\n${url}`; }
async function copyProductLink(product: Product) { const url = directProductUrl(product); try { await navigator.clipboard.writeText(url); return true; } catch { return false; } }
function wrapCanvasText(ctx: CanvasRenderingContext2D, text: string, maxWidth: number) {
  const words = text.trim().split(/\s+/).filter(Boolean);
  const lines: string[] = [];
  let line = "";
  for (const word of words) {
    const candidate = line ? `${line} ${word}` : word;
    if (line && ctx.measureText(candidate).width > maxWidth) { lines.push(line); line = word; }
    else line = candidate;
  }
  if (line) lines.push(line);
  return lines;
}

function drawCanvasText(ctx: CanvasRenderingContext2D, text: string, x: number, y: number, maxWidth: number, lineHeight: number, maxLines = 3) {
  const lines = wrapCanvasText(ctx, text, maxWidth).slice(0, maxLines);
  lines.forEach((line, index) => ctx.fillText(line, x, y + index * lineHeight));
  return y + lines.length * lineHeight;
}

async function downloadShareCard(product: Product) {
  const canvas = document.createElement("canvas");
  canvas.width = 1400;
  canvas.height = 900;
  const ctx = canvas.getContext("2d");
  if (!ctx) return;
  const left = 76;
  const textWidth = 650;
  const price = product.promoPrice || product.price;
  const installment = formatInstallment10x(price);

  const background = ctx.createLinearGradient(0, 0, canvas.width, canvas.height);
  background.addColorStop(0, "#061324");
  background.addColorStop(1, "#0b5c83");
  ctx.fillStyle = background;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = "rgba(29,184,255,.12)";
  ctx.beginPath();
  ctx.arc(1120, 350, 360, 0, Math.PI * 2);
  ctx.fill();

  ctx.fillStyle = "#1db8ff";
  ctx.fillRect(left, 78, 58, 5);
  ctx.fillStyle = "#8db5cc";
  ctx.font = "500 24px Arial";
  ctx.fillText("C7 STORE  ·  TECNOLOGIA SEMINOVA", left, 125);

  ctx.fillStyle = "#f5fbff";
  ctx.font = "700 58px Arial";
  let y = drawCanvasText(ctx, `${product.brand} ${product.model}`, left, 225, textWidth, 66, 2);
  y += 20;

  ctx.fillStyle = "#9fc1d5";
  ctx.font = "400 28px Arial";
  const specs = [product.processor, product.ram, product.storage, product.screen].filter(Boolean).join("  ·  ");
  y = drawCanvasText(ctx, specs, left, y, textWidth, 38, 3);
  y += 24;

  if (installment) {
    ctx.fillStyle = "#1db8ff";
    ctx.font = "700 46px Arial";
    y = drawCanvasText(ctx, installment, left, y, textWidth, 54, 2);
    ctx.fillStyle = "#b7dfed";
    ctx.font = "400 21px Arial";
    ctx.fillText(`À vista: ${price}`, left, y + 6);
    y += 52;
  } else {
    ctx.fillStyle = "#1db8ff";
    ctx.font = "700 46px Arial";
    y = drawCanvasText(ctx, price, left, y, textWidth, 54, 2);
    y += 42;
  }

  ctx.fillStyle = "#b7dfed";
  ctx.font = "600 25px Arial";
  y = drawCanvasText(ctx, "✓ 1 ano de garantia C7 Store", left, y, textWidth, 32, 1);
  ctx.fillStyle = "#7894a8";
  ctx.font = "400 22px Arial";
  drawCanvasText(ctx, "Equipamento revisado e pronto para uso", left, y + 20, textWidth, 30, 2);

  const photoX = 770;
  const photoY = 148;
  const photoWidth = 580;
  const photoHeight = 520;
  let image: HTMLImageElement | null = null;
  if (product.imageUrl) {
    try {
      image = new Image();
      image.crossOrigin = "anonymous";
      await new Promise((resolve, reject) => { image!.onload = resolve; image!.onerror = reject; image!.src = product.imageUrl!; });
    } catch {
      image = null;
    }
  }

  // Use the source image as a soft backdrop to fill the area without cropping
  // the main photo. The foreground always preserves its original proportion.
  ctx.save();
  ctx.beginPath();
  ctx.roundRect(photoX - 18, photoY - 18, photoWidth + 36, photoHeight + 36, 18);
  ctx.clip();
  if (image) {
    const coverScale = Math.max(photoWidth / image.width, photoHeight / image.height);
    const coverWidth = image.width * coverScale;
    const coverHeight = image.height * coverScale;
    ctx.filter = "blur(22px)";
    ctx.globalAlpha = 0.42;
    ctx.drawImage(image, photoX + (photoWidth - coverWidth) / 2, photoY + (photoHeight - coverHeight) / 2, coverWidth, coverHeight);
    ctx.filter = "none";
    ctx.globalAlpha = 1;
    ctx.fillStyle = "rgba(6,19,36,.22)";
    ctx.fillRect(photoX - 18, photoY - 18, photoWidth + 36, photoHeight + 36);
  } else {
    ctx.fillStyle = "#123a53";
    ctx.fillRect(photoX - 18, photoY - 18, photoWidth + 36, photoHeight + 36);
  }
  ctx.restore();

  ctx.fillStyle = "rgba(241,251,255,.10)";
  ctx.fillRect(photoX - 18, photoY - 18, photoWidth + 36, photoHeight + 36);
  ctx.strokeStyle = "rgba(29,184,255,.62)";
  ctx.lineWidth = 3;
  ctx.strokeRect(photoX - 18, photoY - 18, photoWidth + 36, photoHeight + 36);

  if (image) {
    const scale = Math.min(photoWidth / image.width, photoHeight / image.height, 1.35);
    const drawWidth = image.width * scale;
    const drawHeight = image.height * scale;
    ctx.fillStyle = "rgba(234,243,247,.94)";
    ctx.fillRect(photoX, photoY, photoWidth, photoHeight);
    ctx.drawImage(image, photoX + (photoWidth - drawWidth) / 2, photoY + (photoHeight - drawHeight) / 2, drawWidth, drawHeight);
  } else {
    ctx.strokeStyle = "#1db8ff";
    ctx.strokeRect(photoX, photoY, photoWidth, photoHeight);
  }

  ctx.fillStyle = "#f5fbff";
  ctx.font = "600 21px Arial";
  ctx.fillText("WhatsApp (51) 3055-3090  ·  @c7tec_store", left, 820);
  const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/png"));
  if (!blob) return;
  const link = document.createElement("a");
  link.download = `c7-${product.brand}-${product.model}-card.png`.replace(/\s+/g, "-");
  link.href = URL.createObjectURL(blob);
  link.click();
  URL.revokeObjectURL(link.href);
}

function AdaptiveProductImage({ product }: { product: Product }) {
  const [ratio, setRatio] = useState<number | null>(null);
  return <div className="product-image-frame" style={ratio ? { aspectRatio: String(ratio) } : undefined}>
    <img className="product-image" src={product.imageUrl!} alt={`${product.brand} ${product.model}`} onLoad={(event) => {
      const image = event.currentTarget;
      if (image.naturalWidth && image.naturalHeight) setRatio(image.naturalWidth / image.naturalHeight);
    }} />
  </div>;
}

function ProductCard({ product, onSelect, comparing, onCompare, onShare, onTrack }: { product: Product; onSelect: (product: Product) => void; comparing: boolean; onCompare: (product: Product) => void; onShare: (product: Product) => void; onTrack: (eventType: "product_interest" | "product_detail" | "product_share" | "product_compare", productId?: number) => void }) {
  return <article className="product-card"><div className={`product-visual ${product.imageUrl ? "has-product-image" : ""}`}>{product.imageUrl ? <AdaptiveProductImage product={product} /> : <><div className="visual-grid" /><div className="device-glow" />{product.category === "Notebook" ? <Laptop size={66} strokeWidth={1.1} /> : <Monitor size={66} strokeWidth={1.1} />}</>}<span className="category-pill">{product.category}</span><span className="condition-pill"><ShieldCheck size={11} /> {product.condition}</span>{product.badge && <span className="product-badge"><Sparkles size={12} />{product.badge}</span>}</div><div className="product-body"><div className="brand-line">{product.brand}</div><div className="generation-line">{product.generation}</div><div className="guarantee-inline"><ShieldCheck className="guarantee-icon" size={14} aria-hidden="true" /> <span>1 ano de garantia C7 Store</span></div><h3 className="product-model">{product.model}</h3><>{visible(product.processor) && <p className="processor-line"><Cpu size={15} /> {product.processor}</p>}<div className="spec-row">{visible(product.ram) && <span><MemoryStick size={14} /> {product.ram}</span>}{visible(product.storage) && <span><HardDrive size={14} /> {product.storage}</span>}{visible(product.screen) && <span><Monitor size={14} /> {product.screen}</span>}</div></><div className="product-footer"><div><small>{product.promoPrice ? "Oferta" : "Valor"}</small>{product.originalPrice && product.promoPrice && <del>{product.originalPrice}</del>}<strong>{product.promoPrice || product.price}</strong></div><div className="product-actions"><a className="product-interest-button" href={whatsappFor(product)} target="_blank" rel="noreferrer" onClick={() => onTrack("product_interest", product.id)} aria-label={`Tenho interesse em ${product.brand} ${product.model}`}><MessageCircle size={14} /><span>Tenho interesse</span></a><button className={`compare-button ${comparing ? "is-active" : ""}`} onClick={() => { onTrack("product_compare", product.id); onCompare(product); }} aria-label={comparing ? "Remover da comparação" : "Adicionar à comparação"} title={comparing ? "Remover da comparação" : "Adicionar à comparação"}><GitCompareArrows size={15} /><span>{comparing ? "Selecionado" : "Comparar"}</span></button><button className="share-button" onClick={() => { onTrack("product_share", product.id); onShare(product); }} aria-label="Compartilhar produto" title="Compartilhar produto"><Share2 size={15} /></button><button className="text-button" onClick={() => { onTrack("product_detail", product.id); onSelect(product); }}>Ver detalhes <ArrowUpRight size={16} /></button></div></div></div></article>;
}

function MediaGallery({ items, productName }: { items: Array<{ url: string; caption?: string | null; mediaType?: "image" | "video" }>; productName: string }) {
  const safeItems = items.filter((item, index, list) => list.findIndex((candidate) => candidate.url === item.url) === index);
  const [selected, setSelected] = useState(0);
  const [mediaFilter, setMediaFilter] = useState<"all" | "image" | "video">("all");
  const [zoomOpen, setZoomOpen] = useState(false);
  const [zoom, setZoom] = useState(1);
  const [pointerStart, setPointerStart] = useState<number | null>(null);
  const [lightboxPointerStart, setLightboxPointerStart] = useState<number | null>(null);
  const lightboxRef = useRef<HTMLDivElement>(null);
  const visibleItems = useMemo(() => safeItems.filter((item) => mediaFilter === "all" || (mediaFilter === "video" ? item.mediaType === "video" : item.mediaType !== "video")), [safeItems, mediaFilter]);
  const imageItems = safeItems.filter((item) => item.mediaType !== "video");
  const current = safeItems[selected];
  const currentVisibleIndex = visibleItems.findIndex((item) => item.url === current?.url);
  const photoCount = safeItems.filter((item) => item.mediaType !== "video").length;
  const videoCount = safeItems.filter((item) => item.mediaType === "video").length;
  function selectItem(item: (typeof safeItems)[number]) { const index = safeItems.findIndex((candidate) => candidate.url === item.url); if (index >= 0) { setSelected(index); setZoom(1); } }
  function next(step: number) { if (visibleItems.length < 2) return; const nextVisible = visibleItems[(currentVisibleIndex + step + visibleItems.length) % visibleItems.length]; if (nextVisible) selectItem(nextVisible); }
  useEffect(() => { setSelected(0); setMediaFilter("all"); setZoom(1); }, [items.map((item) => item.url).join("|")]);
  useEffect(() => { if (visibleItems.length && !visibleItems.some((item) => item.url === current?.url)) selectItem(visibleItems[0]); }, [mediaFilter]);
  function nextImage(step: number) { if (imageItems.length < 2) return; const currentImageIndex = imageItems.findIndex((item) => item.url === current?.url); selectItem(imageItems[(currentImageIndex + step + imageItems.length) % imageItems.length]); }
  function openZoom() { setZoom(1); setZoomOpen(true); }
  function closeZoom() { setZoom(1); setZoomOpen(false); }
  useEffect(() => { if (zoomOpen) lightboxRef.current?.focus(); }, [zoomOpen]);
  if (!current) return null;
  const currentType = current.mediaType === "video" ? "Vídeo" : "Foto";
  return <>
    <div className="media-gallery">
      <div className="media-gallery-header"><div><strong>Galeria do equipamento</strong><span>{photoCount} {photoCount === 1 ? "foto" : "fotos"}{videoCount ? ` · ${videoCount} ${videoCount === 1 ? "vídeo" : "vídeos"}` : ""}</span></div><div className="media-gallery-filter" role="group" aria-label="Filtrar galeria"><button type="button" className={mediaFilter === "all" ? "is-active" : ""} aria-pressed={mediaFilter === "all"} onClick={() => setMediaFilter("all")}>Tudo</button><button type="button" className={mediaFilter === "image" ? "is-active" : ""} aria-pressed={mediaFilter === "image"} onClick={() => setMediaFilter("image")}>Fotos</button>{videoCount > 0 && <button type="button" className={mediaFilter === "video" ? "is-active" : ""} aria-pressed={mediaFilter === "video"} onClick={() => setMediaFilter("video")}>Vídeos</button>}</div></div>
      <div className="media-gallery-stage" tabIndex={0} onKeyDown={(event) => { if (event.key === "ArrowLeft") next(-1); if (event.key === "ArrowRight") next(1); if (event.key === "Escape") closeZoom(); }} onPointerDown={(event) => { event.currentTarget.setPointerCapture?.(event.pointerId); setPointerStart(event.clientX); }} onPointerUp={(event) => { if (pointerStart !== null && Math.abs(event.clientX - pointerStart) > 35) next(event.clientX < pointerStart ? 1 : -1); setPointerStart(null); }} onPointerCancel={() => setPointerStart(null)} onDoubleClick={() => current.mediaType !== "video" && openZoom()}>
        {current.mediaType === "video" ? <video src={current.url} controls playsInline preload="metadata" aria-label={current.caption || `Vídeo de ${productName}`} /> : <img src={current.url} alt={current.caption || productName} />}
        {visibleItems.length > 1 && <><button type="button" className="media-stage-nav media-stage-prev" onClick={() => next(-1)} aria-label="Mídia anterior"><ArrowLeft size={17} /></button><button type="button" className="media-stage-nav media-stage-next" onClick={() => next(1)} aria-label="Próxima mídia"><ArrowRight size={17} /></button></>}
        <span className="media-gallery-badge">{currentType} {currentVisibleIndex + 1} de {visibleItems.length}</span>
        {current.mediaType !== "video" && <button type="button" className="media-zoom-button" onClick={openZoom}><Maximize2 size={14} /> Ampliar foto</button>}
      </div>
      <div className="media-gallery-caption"><strong>{current.caption || `${currentType} do equipamento`}</strong><span>Use as setas, deslize ou escolha uma miniatura para navegar.</span></div>
      {visibleItems.length > 1 && <div className="media-gallery-controls"><button type="button" onClick={() => next(-1)} aria-label="Mídia anterior"><ArrowLeft size={15} /></button><div className="media-gallery-thumbs" role="list" aria-label="Mídias do equipamento">{visibleItems.map((item, index) => <button type="button" key={item.url} className={item.url === current.url ? "is-selected" : ""} onClick={() => selectItem(item)} aria-current={item.url === current.url ? "true" : undefined} aria-label={`${item.mediaType === "video" ? "Vídeo" : "Foto"} ${index + 1}${item.caption ? `: ${item.caption}` : ""}`}><span className="media-thumb-index">{index + 1}</span>{item.mediaType === "video" ? <video src={item.url} muted playsInline preload="metadata" /> : <img src={item.url} alt="" />}{item.mediaType === "video" && <span className="media-thumb-type">▶ Vídeo</span>}</button>)}</div><button type="button" onClick={() => next(1)} aria-label="Próxima mídia"><ArrowRight size={15} /></button></div>}
      <small className="media-gallery-help">{visibleItems.length > 1 ? `${visibleItems.length} mídias disponíveis · escolha uma miniatura para abrir diretamente.` : "Esta é a mídia disponível deste equipamento."}</small>
    </div>
    {zoomOpen && current.mediaType !== "video" && <div ref={lightboxRef} className="photo-lightbox" role="dialog" aria-modal="true" aria-label={`Foto ampliada de ${productName}`} tabIndex={-1} onKeyDown={(event) => { if (event.key === "Escape") closeZoom(); if (event.key === "ArrowLeft") nextImage(-1); if (event.key === "ArrowRight") nextImage(1); }} onMouseDown={(event) => event.target === event.currentTarget && closeZoom()} onPointerDown={(event) => { event.currentTarget.setPointerCapture?.(event.pointerId); setLightboxPointerStart(event.clientX); }} onPointerUp={(event) => { if (lightboxPointerStart !== null && Math.abs(event.clientX - lightboxPointerStart) > 45) nextImage(event.clientX < lightboxPointerStart ? 1 : -1); setLightboxPointerStart(null); }} onPointerCancel={() => setLightboxPointerStart(null)}>{imageItems.length > 1 && <><button type="button" className="photo-lightbox-nav photo-lightbox-prev" onClick={() => nextImage(-1)} aria-label="Foto anterior"><ArrowLeft size={22} /></button><button type="button" className="photo-lightbox-nav photo-lightbox-next" onClick={() => nextImage(1)} aria-label="Próxima foto"><ArrowRight size={22} /></button></>}<button type="button" className="photo-lightbox-close" onClick={closeZoom} aria-label="Fechar foto ampliada"><X size={20} /></button><div className="photo-lightbox-toolbar"><button type="button" onClick={() => setZoom((value) => Math.max(1, value - .25))} aria-label="Reduzir zoom"><ZoomOut size={17} /></button><span>{Math.round(zoom * 100)}%</span><button type="button" onClick={() => setZoom((value) => Math.min(3, value + .25))} aria-label="Aumentar zoom"><ZoomIn size={17} /></button></div><span className="photo-lightbox-hint">Deslize ou use as setas para trocar a foto</span><img className="photo-lightbox-image" style={{ transform: `scale(${zoom})` }} onClick={() => setZoom((value) => value >= 3 ? 1 : value + .5)} src={current.url} alt={current.caption || productName} draggable={false} /></div>}
  </>;
}

function AdvisorModal({ products, onClose, onSelect, onTrack }: { products: Product[]; onClose: () => void; onSelect: (product: Product) => void; onTrack: (eventType: "advisor_whatsapp", productId?: number) => void }) {
  const [step, setStep] = useState(0);
  const [goal, setGoal] = useState("");
  const [mobility, setMobility] = useState("");
  const [budget, setBudget] = useState("");
  const [priority, setPriority] = useState("");
  const [gameChoice, setGameChoice] = useState("");
  const [gameOther, setGameOther] = useState("");
  const [programChoice, setProgramChoice] = useState("");
  const [programOther, setProgramOther] = useState("");
  const [customBuild, setCustomBuild] = useState(false);
  const [customType, setCustomType] = useState("Notebook");
  const [customCategory, setCustomCategory] = useState("Escritório");
  const [customUse, setCustomUse] = useState("");
  const [customBudget, setCustomBudget] = useState("");
  const [customSpecs, setCustomSpecs] = useState("");
  const [customNotes, setCustomNotes] = useState(""); const [freeText, setFreeText] = useState("");
  const totalSteps = goal === "jogos" || goal === "criacao" ? 5 : 4;
  const mobilityOptions = [{ value: "leve", label: "Sim, quero levar comigo", text: "Priorizar notebook e praticidade", icon: "↗" }, { value: "asvezes", label: "Às vezes", text: "Equilíbrio entre mobilidade e tela", icon: "↔" }, { value: "fixo", label: "Não, ficará em um lugar", text: "Desktop também pode ser uma opção", icon: "▣" }, { value: "tanto-faz", label: "Tanto faz", text: "Escolher pela configuração", icon: "○" }];
  const budgetOptions = [{ value: "ate-1500", label: "Até R$ 1.500", text: "O essencial pelo menor valor", icon: "$" }, { value: "ate-2500", label: "De R$ 1.500 a R$ 2.500", text: "Equilíbrio para a maioria das tarefas", icon: "$" }, { value: "ate-4000", label: "De R$ 2.500 a R$ 4.000", text: "Mais conforto e desempenho", icon: "$$" }, { value: "acima-4000", label: "Acima de R$ 4.000", text: "Quero mais potência", icon: "$$$" }, { value: "qualquer", label: "Ainda não sei", text: "Mostre as melhores opções", icon: "?" }];
  const priorityOptions = [{ value: "preco", label: "Gastar o mínimo possível", text: "Quero uma opção econômica", icon: "$" }, { value: "rapidez", label: "Abrir tudo rapidamente", text: "Quero agilidade no dia a dia", icon: "⚡" }, { value: "desempenho", label: "Ter mais desempenho", text: "Quero mais potência", icon: "✦" }, { value: "equilibrio", label: "Melhor escolha pelo preço", text: "Quero custo-benefício", icon: "✓" }, { value: "nao-sei", label: "Ainda não sei", text: "Me mostre uma escolha segura", icon: "?" }];
  const gameOptions = [{ value: "cyberpunk", label: "Cyberpunk 2077 / Red Dead Redemption 2", text: "Muito pesados · placa de vídeo dedicada", icon: "◆" }, { value: "warzone", label: "Warzone / Fortnite / Apex Legends", text: "Competitivos · alto desempenho", icon: "◈" }, { value: "gta", label: "GTA V / Forza Horizon / EA FC", text: "Intermediários · boa GPU e memória", icon: "◇" }, { value: "minecraft", label: "Minecraft / Roblox / The Sims", text: "Leves a intermediários · flexíveis", icon: "◌" }, { value: "outro", label: "Outro jogo", text: "Digite o nome e analisaremos com você", icon: "✎" }];
  const programOptions = [{ value: "photoshop", label: "Photoshop, Canva ou Figma", text: "Fotos, artes e criação visual", icon: "✦" }, { value: "premiere", label: "Premiere, DaVinci ou After Effects", text: "Edição de vídeo e projetos pesados", icon: "◆" }, { value: "autocad", label: "AutoCAD, 3D ou engenharia", text: "Projetos técnicos e modelagem", icon: "◇" }, { value: "outro", label: "Outro programa", text: "Digite o nome e analisaremos com cautela", icon: "✎" }];
  const options = step === 0 ? [{ value: "estudo", label: "Estudar e assistir aulas", text: "Pesquisas, vídeos e tarefas do dia a dia", icon: "◌" }, { value: "trabalho", label: "Trabalhar", text: "Documentos, sistemas e atendimento", icon: "⌘" }, { value: "criacao", label: "Editar fotos e vídeos", text: "Design, criação e tarefas pesadas", icon: "✦" }, { value: "jogos", label: "Jogar", text: "Escolha seus jogos para uma recomendação mais precisa", icon: "◈" }, { value: "basico", label: "Navegar e assistir vídeos", text: "Uso simples, rápido e econômico", icon: "○" }, { value: "desktop", label: "Usar um desktop potente ou empresarial", text: "Para uso fixo, desempenho e possibilidade de montagem personalizada", icon: "▣" }, { value: "montar", label: "Quero montar um computador específico", text: "Envie seus requisitos para a equipe C7", icon: "✚" }] : goal === "jogos" && step === 1 ? gameOptions : goal === "criacao" && step === 1 ? programOptions : goal === "jogos" && step === 2 ? mobilityOptions : goal === "criacao" && step === 2 ? mobilityOptions : goal === "jogos" && step === 3 ? budgetOptions : goal === "criacao" && step === 3 ? budgetOptions : step === 1 ? mobilityOptions : step === 2 ? budgetOptions : priorityOptions;
  const available = products.filter((product) => product.status === "available");
  const ranked = step === totalSteps ? recommendProducts(available, { goal, mobility, budget, priority, gameChoice, programChoice, freeText: freeText || (goal === "jogos" ? gameOther : programOther) }) : [];
  const recommendationMatches = ranked.slice(0, 3);
  const recommendations = recommendationMatches.map((item) => item.product);
  const main = recommendations[0];
  const suggestCustomDesktop = step === totalSteps && shouldSuggestCustomDesktop({ goal, mobility, budget, priority });
  const conversation = advisorConversation({ goal, mobility, budget, priority, step, totalSteps });
  function startFromMessage() { const interpreted = interpretAdvisorFreeText(freeText); if (interpreted.goal === "montar") { setCustomType("Desktop"); setCustomCategory("Personalizada"); setCustomUse("Computador personalizado"); setCustomNotes(freeText.trim()); setCustomBuild(true); return; } setGoal(interpreted.goal); setStep(1); }
  function choose(value: string) { if (step === 0 && value === "montar") { setCustomBuild(true); return; } if (step === 0) setGoal(value); if (goal === "jogos" && step === 1) { setGameChoice(value); if (value === "outro") return; } if (goal === "criacao" && step === 1) { setProgramChoice(value); if (value === "outro") return; } if (goal === "jogos" && step === 2) setMobility(value); if (goal === "criacao" && step === 2) setMobility(value); if (goal === "jogos" && step === 3) setBudget(value); if (goal === "criacao" && step === 3) setBudget(value); if (goal === "jogos" && step === 4) setPriority(value); if (goal === "criacao" && step === 4) setPriority(value); if (goal !== "jogos" && goal !== "criacao" && step === 1) setMobility(value); if (goal !== "jogos" && goal !== "criacao" && step === 2) setBudget(value); if (goal !== "jogos" && goal !== "criacao" && step === 3) setPriority(value); setStep((current) => current + 1); }
  function continueGame() { if (gameOther.trim()) setStep(2); }
  function continueProgram() { if (programOther.trim()) setStep(2); }
  function resultReason(product: Product) { const match = ranked.find((item) => item.product.id === product.id); return match?.reasons.join(" e ") || (goal === "jogos" ? `analisado para ${analyzeGame(gameChoice, gameOther).label}` : goal === "criacao" ? `analisado para ${programChoice || programOther || "seu programa"}` : "configuração compatível com suas respostas"); }
  function whatsappRecommendation() { onTrack("advisor_whatsapp"); const names = recommendations.map((product, index) => `${index + 1}. ${product.brand} ${product.model} — ${product.promoPrice || product.price} (${resultReason(product)})`).join("\n"); const goalLabel = goal || "não informado"; const budgetLabel = budget || "não informado"; const mobilityLabel = mobility || "não informado"; const priorityLabel = priority || "não informado"; const gameLabel = goal === "jogos" ? `\nJogo de referência: ${gameChoice === "outro" ? gameOther || "não informado" : gameChoice || "não informado"}` : ""; const message = `Olá! Usei o Encontrar meu computador da C7 Store e gostaria de confirmar estas opções:\n\n${names}\n\nMeu perfil:\n• Finalidade: ${goalLabel}${gameLabel}\n• Mobilidade: ${mobilityLabel}\n• Orçamento: ${budgetLabel}\n• Prioridade: ${priorityLabel}\n\nPodem confirmar disponibilidade, garantia de 1 ano e condições de pagamento?`; window.open(`${WHATSAPP}?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer"); }
  function openCustomDesktopBuild() { setCustomType("Desktop"); setCustomCategory("Personalizada"); setCustomUse("Desktop potente montado sob medida"); setCustomSpecs(""); setCustomNotes("Quero uma configuração com foco em desempenho."); setCustomBuild(true); }
  function sendCustomRequest(event: React.FormEvent) { event.preventDefault(); const message = `Olá! Gostaria de solicitar um computador montado sob medida pela C7 Store.\n\nTipo: ${customType}\nCategoria de montagem: ${customCategory}\nUso principal: ${customUse || "Não informado"}\nOrçamento: ${customBudget || "Não informado"}\nConfiguração desejada: ${customSpecs || "Não informado"}\nObservações: ${customNotes || "Nenhuma"}\n\nPodem me orientar sobre disponibilidade e prazo?`; window.open(`${WHATSAPP}?text=${encodeURIComponent(message)}`, "_blank", "noopener,noreferrer"); }
  const titles = goal === "jogos" ? ["Qual será o principal uso?", "Qual jogo você quer jogar?", "Você precisa levar o equipamento?", "Qual faixa de valor combina com você?", "O que pesa mais na sua decisão?"] : goal === "criacao" ? ["Qual será o principal uso?", "Qual programa você usa?", "Você precisa levar o equipamento?", "Qual faixa de valor combina com você?", "O que pesa mais na sua decisão?"] : ["Qual será o principal uso?", "Você precisa levar o equipamento?", "Qual faixa de valor combina com você?", "O que pesa mais na sua decisão?"];
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="advisor-modal advisor-commercial-modal" role="dialog" aria-modal="true" aria-labelledby="advisor-title"><button className="close-button" onClick={onClose} aria-label="Fechar assistente"><X size={18} /></button><div className="advisor-kicker"><Bot size={15} /> Consultora C7 <span className="advisor-kicker-note">atendimento próximo</span></div>{customBuild ? <><h2 id="advisor-title">Vamos montar isso juntos.</h2><p className="advisor-intro">Me conte o que você imagina e eu organizo suas necessidades para a equipe C7 retornar com configuração, preço e prazo.</p><form className="custom-build-form" onSubmit={sendCustomRequest}><label><span>Tipo de equipamento</span><select value={customType} onChange={(event) => setCustomType(event.target.value)}><option>Notebook</option><option>Desktop</option><option>Ainda não sei</option></select></label><label><span>Categoria de montagem</span><select value={customCategory} onChange={(event) => setCustomCategory(event.target.value)}><option>Escritório</option><option>Gamer</option><option>Edição e criação</option><option>Estudos e uso básico</option><option>Empresa e atendimento</option><option>Personalizada</option></select></label><label><span>Uso principal</span><input value={customUse} onChange={(event) => setCustomUse(event.target.value)} placeholder="Ex.: escritório, jogos, edição, estudos" required /></label><label><span>Orçamento aproximado</span><input value={customBudget} onChange={(event) => setCustomBudget(event.target.value)} placeholder="Ex.: até R$ 3.000" required /></label><label><span>Configuração que você deseja</span><textarea value={customSpecs} onChange={(event) => setCustomSpecs(event.target.value)} placeholder="Ex.: 16 GB RAM, SSD 512 GB, placa de vídeo..." rows={3} /></label><label><span>Observações</span><textarea value={customNotes} onChange={(event) => setCustomNotes(event.target.value)} placeholder="Tamanho da tela, marcas, quantidade ou outra preferência" rows={2} /></label><div className="custom-build-actions"><button type="button" className="advisor-back" onClick={() => setCustomBuild(false)}>Voltar</button><button type="submit" className="primary-button"><MessageCircle size={16} /> Enviar pedido no WhatsApp</button></div></form></> : step < totalSteps ? <><h2 id="advisor-title">{conversation.title}</h2><p className="advisor-intro">{conversation.intro}</p>{step === 0 && <div className="advisor-free-text"><label htmlFor="advisor-message">Ou me conte do seu jeito</label><textarea id="advisor-message" value={freeText} onChange={(event) => setFreeText(event.target.value)} placeholder="Ex.: preciso de um notebook para estudar e trabalhar, até R$ 2.500" rows={3} /><button type="button" className="advisor-message-button" onClick={startFromMessage} disabled={!freeText.trim()}>Analisar minha necessidade <ArrowRight size={15} /></button></div>}<div className="advisor-progress"><span style={{ width: `${((step + 1) / totalSteps) * 100}%` }} /></div><h3>{titles[step]}</h3><div className="advisor-options">{options.map((option) => <button type="button" key={option.value} onClick={() => choose(option.value)}><i>{"icon" in option ? option.icon : "✓"}</i><span><strong>{option.label}</strong><small>{option.text}</small></span><ArrowRight size={15} /></button>)}</div>{goal === "jogos" && step === 1 && gameChoice === "outro" && <div className="game-custom-input"><label htmlFor="game-name">Digite o nome do jogo</label><div><input id="game-name" value={gameOther} onChange={(event) => setGameOther(event.target.value)} placeholder="Ex.: Valorant, Elden Ring ou outro" /><button type="button" className="primary-button" onClick={continueGame} disabled={!gameOther.trim()}>Continuar <ArrowRight size={15} /></button></div></div>}{goal === "criacao" && step === 1 && programChoice === "outro" && <div className="game-custom-input"><label htmlFor="program-name">Digite o nome do programa</label><div><input id="program-name" value={programOther} onChange={(event) => setProgramOther(event.target.value)} placeholder="Ex.: Blender, AutoCAD ou outro" /><button type="button" className="primary-button" onClick={continueProgram} disabled={!programOther.trim()}>Continuar <ArrowRight size={15} /></button></div></div>}{step > 0 && <button type="button" className="advisor-back" onClick={() => setStep((current) => current - 1)}>Voltar</button>}</> : <><h2 id="advisor-title">{conversation.title}</h2><p className="advisor-intro">{conversation.intro}</p>{suggestCustomDesktop && <div className="advisor-build-callout" role="status"><div><strong>Quer um desktop ainda mais potente?</strong><span>Podemos montar uma configuração sob medida para jogos, edição ou alto desempenho, mesmo que ela não esteja pronta no estoque.</span></div><button type="button" className="primary-button" onClick={openCustomDesktopBuild}><Cpu size={16} /> Montar meu desktop</button></div>}{!main && <div className="advisor-empty-result" role="status"><strong>Não encontramos uma combinação ideal no estoque atual.</strong><span>Podemos confirmar uma configuração personalizada pelo WhatsApp.</span></div>}{main && <div className="advisor-main-result"><span>{recommendationLabel(recommendationMatches[0])} · {recommendationMatches[0]?.compatibility ?? 0}% compatível</span><strong>{main.brand} {main.model}</strong><p>Por que pensei nela: {resultReason(main)}.</p>{recommendationMatches[0]?.limitations.length ? <small className="advisor-limitations">Atenção: {recommendationMatches[0].limitations.join("; ")}.</small> : <small className="advisor-fit">Compatível com as prioridades informadas.</small>}<b>{main.promoPrice || main.price} · 1 ano de garantia</b><button type="button" className="primary-button" onClick={() => { onSelect(main); onClose(); }}>Ver ficha e fotos <ArrowUpRight size={15} /></button></div>}<div className="advisor-results">{recommendations.slice(1).map((product, index) => <button type="button" className="advisor-result" key={product.id} onClick={() => { onSelect(product); onClose(); }}><span className="advisor-rank">0{index + 2}</span>{product.imageUrl ? <img src={product.imageUrl} alt="" /> : <Laptop size={35} />}<div><strong>{product.brand} {product.model}</strong><span>{product.processor} · {product.ram} · {product.storage}</span><small className="advisor-fit">{recommendationLabel(recommendationMatches[index + 1])} · {recommendationMatches[index + 1]?.compatibility ?? 0}% compatível · {recommendationMatches[index + 1]?.limitations.length ? "tem limitações" : index === 0 ? "alternativa mais econômica" : "alternativa com mais desempenho"}</small>{recommendationMatches[index + 1]?.limitations.length ? <small className="advisor-limitations">{recommendationMatches[index + 1].limitations[0]}</small> : null}<b>{product.promoPrice || product.price}</b></div><ArrowUpRight size={16} /></button>)}</div>{recommendations.length > 0 && <button type="button" className="primary-button advisor-whatsapp" onClick={whatsappRecommendation}><MessageCircle size={16} /> Enviar opções no WhatsApp</button>}<p className="advisor-human-note"><strong>Quer ajustar alguma resposta?</strong> Você pode voltar e refazer o caminho — eu continuo te ajudando.</p><button type="button" className="advisor-back" onClick={() => setStep(0)}>Refazer respostas</button></>}</div></div>;
}

function DetailsModal({ product, onClose, onTrack }: { product: Product; onClose: () => void; onTrack: (eventType: "product_interest", productId?: number) => void }) {
  const { data } = trpc.products.detail.useQuery({ id: product.id });
  const gallery = data?.images ?? [];
  const sharedGalleryMode = typeof window !== "undefined" && new URLSearchParams(window.location.search).get("galeria") === "principal" ? "primary" : "all";
  const images = (sharedGalleryMode === "primary" ? [product.imageUrl ? { url: product.imageUrl, caption: "Foto principal", mediaType: "image" as const } : null] : [product.imageUrl ? { url: product.imageUrl, caption: "Foto principal", mediaType: "image" as const } : null, ...gallery]).filter(Boolean) as Array<{ url: string; caption?: string | null; mediaType?: "image" | "video" }>;
  const details = [["Condição", product.condition], ["Conservação", product.cosmeticCondition], ["Processador", product.processor], ["Geração", product.generation], ["Memória", [product.ram, product.ramType].filter(visible).join(" · ")], ["Armazenamento", product.storage], ["Placa de vídeo", product.gpu], ["Sistema operacional", product.os], ["Tela", product.screen], ["Bateria", product.battery], ["Acessórios", product.accessories]].filter(([, value]) => visible(value));
  const installment = formatInstallment10x(product.promoPrice || product.price);
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="details-modal" role="dialog" aria-modal="true" aria-labelledby="details-title"><button className="close-button" onClick={onClose} aria-label="Fechar detalhes"><X size={18} /></button><div className="modal-kicker">Detalhes do equipamento · seminovo revisado</div><div className="details-identity"><div><div className="modal-brand">{product.brand}</div><h2 className="modal-model" id="details-title">{product.model}</h2><p className="modal-intro">Equipamento seminovo revisado e pronto para encontrar um novo dono. Confira fotos, estado e configuração antes de chamar a equipe.</p></div></div><div className="commercial-fit"><span>Perfil recomendado</span><strong>{purposeLabelFor(product)}</strong><small>Configuração conferida pela C7 Store</small></div><div className="guarantee-callout"><span className="guarantee-callout-icon"><ShieldCheck size={18} aria-hidden="true" /></span><div><strong>Compre com 1 ano de garantia</strong><span>Mais tranquilidade e segurança para comprar seu equipamento seminovo revisado.</span></div></div>{images.length > 0 && <><MediaGallery items={images} productName={`${product.brand} ${product.model}`} /></>}<div className="modal-price"><small>Valor à vista</small><strong>{product.promoPrice || product.price}</strong>{product.originalPrice && product.promoPrice && <del>{product.originalPrice}</del>}{installment && <span className="modal-installment"><ShieldCheck size={15} aria-hidden="true" /> {installment}</span>}<span className="modal-price-note"><ShieldCheck size={14} /> 1 ano de garantia · {purposeLabelFor(product)} · consulte condições de pagamento</span></div><div className="details-grid">{details.map(([label, value]) => <div className="detail-item" key={label}><span>{label}</span><strong>{value}</strong></div>)}</div>{product.notes && <div className="modal-notes"><strong>Observações</strong><p>{product.notes}</p></div>}<div className="modal-actions"><a className="primary-button sales-cta" href={whatsappFor(product)} target="_blank" rel="noreferrer" onClick={() => onTrack("product_interest", product.id)}><MessageCircle size={17} /> Tenho interesse neste equipamento</a><button className="secondary-button" onClick={onClose}>Continuar navegando</button></div></div></div>;
}

function numericValue(value: unknown) { const match = String(value ?? "").replace(/\./g, "").replace(",", ".").match(/-?\d+(?:\.\d+)?/); return match ? Number(match[0]) : 0; }
function processorScore(product: Product) { const text = product.processor.toLowerCase(); const family = text.includes("i7") || text.includes("ryzen 7") ? 7 : text.includes("i5") || text.includes("ryzen 5") ? 5 : text.includes("i3") || text.includes("ryzen 3") ? 3 : text.includes("celeron") ? 1 : 2; return family * 100 + numericValue(product.generation) * 3 + numericValue(product.ram); }
function storageScore(value: string) { const text = value.toLowerCase(); const amount = numericValue(text) * (text.includes("tb") ? 1024 : 1); return amount + (text.includes("ssd") ? 10000 : 0); }
function currentPrice(product: Product) { return numericValue(product.promoPrice || product.price); }
function CompareModal({ products, onClose, onSelect, onRemove }: { products: Product[]; onClose: () => void; onSelect: (product: Product) => void; onRemove: (id: number) => void }) {
  const rows: Array<{ group: string; label: string; key: string; getter: (product: Product) => string; rank?: (value: string, product: Product) => number; lower?: boolean }> = [
    { group: "O que você leva", label: "Processador", key: "processor", getter: (product) => product.processor, rank: (_value, product) => processorScore(product) },
    { group: "O que você leva", label: "Memória RAM", key: "ram", getter: (product) => [product.ram, product.ramType].filter(visible).join(" · "), rank: (value) => numericValue(value) },
    { group: "O que você leva", label: "Armazenamento", key: "storage", getter: (product) => product.storage, rank: (value) => storageScore(value) },
    { group: "O que você leva", label: "Finalidade", key: "purpose", getter: (product) => purposeFor(product) },
    { group: "Compra segura", label: "Condição", key: "condition", getter: (product) => product.cosmeticCondition || product.condition },
    { group: "Compra segura", label: "Garantia", key: "warranty", getter: () => "1 ano de garantia" },
    { group: "Compra segura", label: "Preço", key: "price", getter: (product) => product.promoPrice || product.price, rank: (_value, product) => currentPrice(product), lower: true },
  ];
  const recommendations = [
    { label: "Melhor desempenho", product: products.reduce((best, product) => processorScore(product) > processorScore(best) ? product : best, products[0]) },
    { label: "Melhor preço", product: products.reduce((best, product) => currentPrice(product) < currentPrice(best) ? product : best, products[0]) },
    { label: "Melhor custo-benefício", product: products.reduce((best, product) => (processorScore(product) / Math.max(currentPrice(product), 1)) > (processorScore(best) / Math.max(currentPrice(best), 1)) ? product : best, products[0]) },
  ];
  return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="compare-modal" role="dialog" aria-modal="true" aria-labelledby="compare-title"><button className="close-button" onClick={onClose} aria-label="Fechar comparação"><X size={18} /></button><div className="modal-kicker">Comparação de compra · até 3 equipamentos</div><h2 id="compare-title">Escolha o melhor para sua rotina.</h2><p className="compare-intro">Compare apenas o que importa na decisão: configuração, finalidade, garantia e preço. A equipe C7 pode confirmar disponibilidade pelo WhatsApp.</p><div className="compare-headings"><span className="compare-label-cell">Equipamento</span>{products.map((product) => <div className="compare-heading" key={product.id}>{product.imageUrl && <img src={product.imageUrl} alt="" />}<strong>{product.brand} {product.model}</strong><b>{product.promoPrice || product.price}</b><div className="compare-heading-actions"><a href={whatsappFor(product)} target="_blank" rel="noreferrer" className="compare-whatsapp" onClick={(event) => event.stopPropagation()}><MessageCircle size={12} /> WhatsApp</a><button type="button" className="compare-remove" onClick={() => onRemove(product.id)}><X size={12} /> Remover</button></div></div>)}</div><div className="comparison-recommendations">{recommendations.map(({ label, product }) => <button type="button" className="recommendation-card" key={label} onClick={() => onSelect(product)}><span>{label}</span><strong>{product.brand} {product.model}</strong><small>{product.promoPrice || product.price}</small></button>)}</div><div className="compare-table">{Array.from(new Set(rows.map((row) => row.group))).map((group) => <div key={group}><div className="compare-group-title">{group}</div>{rows.filter((row) => row.group === group).map((row) => { const values = products.map((product) => row.getter(product)); if (!values.some(visible)) return null; const ranked = row.rank ? values.map((value, index) => visible(value) ? row.rank?.(value, products[index]!) ?? 0 : (row.lower ? Number.POSITIVE_INFINITY : 0)) : []; const target = row.rank ? (row.lower ? Math.min(...ranked) : Math.max(...ranked)) : null; return <div className="compare-row" key={row.key}><strong>{row.label}</strong>{values.map((value, index) => <span className={row.rank && visible(value) && ranked[index] === target ? "comparison-best" : ""} key={products[index]?.id}>{visible(value) ? value : "—"}{row.rank && visible(value) && ranked[index] === target && <em>melhor</em>}</span>)}</div>; })}</div>)}</div><div className="compare-footer"><span>Precisa confirmar disponibilidade, garantia ou acessórios?</span><a className="primary-button" href={WHATSAPP} target="_blank" rel="noreferrer"><MessageCircle size={15} /> Falar com a C7</a></div></div></div>;
}


function ShareModal({ product, onClose, onTrack }: { product: Product; onClose: () => void; onTrack: (eventType: "product_share", productId?: number) => void }) { const [qr, setQr] = useState(""); const [copied, setCopied] = useState(false); const [galleryMode, setGalleryMode] = useState<"all" | "primary">("all"); const url = directProductUrl(product, galleryMode); useEffect(() => { void QRCode.toDataURL(url, { width: 220, margin: 2, color: { dark: "#061324", light: "#ffffff" } }).then(setQr); }, [url]); async function copy() { try { await navigator.clipboard.writeText(url); setCopied(true); setTimeout(() => setCopied(false), 2200); } catch { setCopied(false); } } return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => event.target === event.currentTarget && onClose()}><div className="share-modal" role="dialog" aria-modal="true" aria-labelledby="share-title"><button className="close-button" onClick={onClose} aria-label="Fechar compartilhamento"><X size={18} /></button><div className="modal-kicker">Compartilhar produto C7 Store</div><h2 id="share-title">Envie este equipamento para o cliente.</h2><div className="share-product-preview">{product.imageUrl ? <img src={product.imageUrl} alt="" /> : <Laptop size={40} />}<div><strong>{product.brand} {product.model}</strong><span>{product.promoPrice || product.price} · 1 ano de garantia</span><small>{purposeLabelFor(product)}</small></div></div><fieldset className="share-gallery-choice"><legend>Como o cliente verá</legend><label><input type="radio" name="share-gallery-mode" checked={galleryMode === "all"} onChange={() => setGalleryMode("all")} /> <span><strong>Galeria completa</strong><small>Mostra todas as fotos e vídeos disponíveis.</small></span></label><label><input type="radio" name="share-gallery-mode" checked={galleryMode === "primary"} onChange={() => setGalleryMode("primary")} /> <span><strong>Somente foto principal</strong><small>Uma apresentação mais rápida e objetiva.</small></span></label></fieldset><div className="share-qr-area">{qr && <img src={qr} alt="QR Code para abrir o produto" />}<div><strong>QR Code do produto</strong><p>O cliente pode apontar a câmera do celular para abrir a ficha completa.</p></div></div><div className="share-actions"><button className="primary-button" onClick={() => { onTrack("product_share", product.id); window.open(`https://wa.me/555130553090?text=${encodeURIComponent(shareText(product, url, galleryMode))}`, "_blank", "noopener,noreferrer"); }}><MessageCircle size={16} /> Enviar no WhatsApp</button><button className="secondary-button" onClick={() => void copy()}><Share2 size={16} /> {copied ? "Link copiado" : "Copiar link"}</button><button className="secondary-button" onClick={() => void downloadShareCard(product)}><DownloadIcon /> Baixar imagem</button></div></div></div>; }
function DownloadIcon() { return <span aria-hidden="true" style={{ fontSize: 16 }}>↓</span>; }
type PublicCampaign = { id: number; slug: string; title: string; description: string | null; bannerUrl: string | null; accentColor: string; ctaLabel: string; products: Product[] };
function CampaignSpotlight({ campaign, onSelect }: { campaign: PublicCampaign; onSelect: (product: Product) => void }) {
  return <section className="campaign-spotlight" style={{ "--campaign-accent": campaign.accentColor } as React.CSSProperties} aria-labelledby={`campaign-title-${campaign.id}`}>
    {campaign.bannerUrl && <div className="campaign-spotlight-image" style={{ backgroundImage: `url(${campaign.bannerUrl})` }} aria-hidden="true" />}
    <div className="campaign-spotlight-content"><div className="campaign-spotlight-copy"><span className="section-kicker">/ destaque da C7 Store</span><h2 id={`campaign-title-${campaign.id}`}>{campaign.title}</h2><p>{campaign.description || "Equipamentos revisados, selecionados para você e com 1 ano de garantia."}</p><a className="campaign-spotlight-cta" href="#campanha-produtos">{campaign.ctaLabel} <ArrowUpRight size={16} /></a></div><div className="campaign-spotlight-products" id="campanha-produtos">{campaign.products.slice(0, 3).map((product) => <button type="button" className="campaign-product-card" key={product.id} onClick={() => onSelect(product)}><span className="campaign-product-image">{product.imageUrl ? <img src={product.imageUrl} alt="" /> : <Laptop size={30} />}</span><span><strong>{product.brand} {product.model}</strong><small>{product.promoPrice || product.price}</small></span><ArrowUpRight size={15} /></button>)}</div></div>
  </section>;
}

export default function Home() {
  const { data, isLoading } = trpc.products.list.useQuery(); const campaignsQuery = trpc.campaigns.list.useQuery(); const products = (data ?? []) as Product[]; const campaignSlug = typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("campanha") : null; const activeCampaign = campaignsQuery.data?.find((campaign) => campaign.slug === campaignSlug) ?? campaignsQuery.data?.[0];
  const [search, setSearch] = useState(""); const [viewMode, setViewMode] = useState<"cards" | "list">(() => { try { return localStorage.getItem("c7-catalog-view") === "list" ? "list" : "cards"; } catch { return "cards"; } }); const [showMobileFilters, setShowMobileFilters] = useState(false); const [showAdvisor, setShowAdvisor] = useState(false); const [brand, setBrand] = useState("Todas"); const [ram, setRam] = useState("Todas"); const [category, setCategory] = useState("Todos"); const [purpose, setPurpose] = useState("Todas"); const [minPrice, setMinPrice] = useState("Todos"); const [offersOnly, setOffersOnly] = useState(false); const [sortBy, setSortBy] = useState("relevantes"); const [sharingProduct, setSharingProduct] = useState<Product | null>(null); const [selectedProduct, setSelectedProduct] = useState<Product | null>(null); const [compareIds, setCompareIds] = useState<number[]>([]); const [showCompare, setShowCompare] = useState(false); const trackEventMutation = trpc.analytics.track.useMutation(); const trackEvent = (eventType: "product_interest" | "product_detail" | "product_share" | "product_compare" | "advisor_open" | "advisor_whatsapp" | "catalog_whatsapp", productId?: number) => { trackEventMutation.mutate({ eventType, productId, source: "catalog", path: typeof window !== "undefined" ? window.location.pathname : "/" }); };
  const brands = ["Todas", ...Array.from(new Set(products.map((product) => product.brand)))]; const ramOptions = ["Todas", ...Array.from(new Set(products.map((product) => product.ram)))];
  const filteredProducts = useMemo(() => { const filtered = products.filter((product) => { const query = search.toLowerCase(); const price = currentPrice(product); const priceOk = minPrice === "Todos" || (minPrice === "ate-1500" ? price > 0 && price <= 1500 : minPrice === "1500-2500" ? price > 1500 && price <= 2500 : minPrice === "2500-4000" ? price > 2500 && price <= 4000 : price > 4000); return [product.brand, product.model, product.processor, product.storage].join(" ").toLowerCase().includes(query) && (brand === "Todas" || product.brand === brand) && (ram === "Todas" || product.ram === ram) && (category === "Todos" || product.category === category) && (purpose === "Todas" || purposeFor(product) === purpose) && priceOk && (!offersOnly || Boolean(product.promoPrice)); }); return [...filtered].sort((a, b) => sortBy === "menor-preco" ? currentPrice(a) - currentPrice(b) : sortBy === "maior-preco" ? currentPrice(b) - currentPrice(a) : sortBy === "ofertas" ? Number(Boolean(b.promoPrice)) - Number(Boolean(a.promoPrice)) || currentPrice(a) - currentPrice(b) : 0); }, [products, search, brand, ram, category, purpose, minPrice, offersOnly, sortBy]);
  const comparingProducts = compareIds.map((id) => products.find((product) => product.id === id)).filter(Boolean) as Product[];
  const clearFilters = () => { setSearch(""); setBrand("Todas"); setRam("Todas"); setCategory("Todos"); setPurpose("Todas"); setMinPrice("Todos"); setOffersOnly(false); setSortBy("relevantes"); };
  function toggleCompare(product: Product) { setCompareIds((current) => current.includes(product.id) ? current.filter((id) => id !== product.id) : current.length >= 3 ? [...current.slice(1), product.id] : [...current, product.id]); }
  useEffect(() => { try { localStorage.setItem("c7-catalog-view", viewMode); } catch {} }, [viewMode]);
  useEffect(() => { const productId = Number(new URLSearchParams(window.location.search).get("produto")); const product = productId ? products.find((item) => item.id === productId) : undefined; if (product) setSelectedProduct(product); const title = product ? `${product.brand} ${product.model} · C7 Store` : "C7 Store · Catálogo de Tecnologia Seminova"; document.title = title; const description = product ? `${product.brand} ${product.model} seminovo revisado, ${product.processor}, ${product.ram}, ${product.storage}, por ${product.promoPrice || product.price}. 1 ano de garantia C7 Store.` : "Notebooks e desktops seminovos revisados, com 1 ano de garantia C7 Store."; const meta = (name: string, content: string, property = false) => { const selector = property ? `meta[property="${name}"]` : `meta[name="${name}"]`; let element = document.head.querySelector(selector) as HTMLMetaElement | null; if (!element) { element = document.createElement("meta"); if (property) element.setAttribute("property", name); else element.setAttribute("name", name); document.head.appendChild(element); } element.content = content; }; meta("description", description); meta("og:title", title, true); meta("og:description", description, true); meta("og:url", window.location.href, true); meta("og:image", product?.imageUrl || `${window.location.origin}${LOGO}`, true);
    const existingSchema = document.head.querySelector('script[data-c7-product-schema="true"]'); existingSchema?.remove();
    if (product) { const priceText = product.promoPrice || product.price || ""; const numericPrice = Number(priceText.replace(/[^0-9,.-]/g, "").replace(/\./g, "").replace(",", ".")); const schema: Record<string, unknown> = { "@context": "https://schema.org", "@type": "Product", name: `${product.brand} ${product.model}`, brand: { "@type": "Brand", name: product.brand }, category: product.category, image: product.imageUrl ? [new URL(product.imageUrl, window.location.origin).toString()] : undefined, description, sku: product.serial && product.serial !== "—" ? product.serial : undefined, additionalProperty: [{ "@type": "PropertyValue", name: "Garantia", value: "1 ano de garantia C7 Store" }] }; if (Number.isFinite(numericPrice) && numericPrice > 0) schema.offers = { "@type": "Offer", priceCurrency: "BRL", price: numericPrice.toFixed(2), availability: "https://schema.org/InStock", url: window.location.href }; const script = document.createElement("script"); script.type = "application/ld+json"; script.dataset.c7ProductSchema = "true"; script.textContent = JSON.stringify(schema); document.head.appendChild(script); }
  }, [products]);
  function closeDetails() { setSelectedProduct(null); if (window.location.search) window.history.replaceState({}, "", window.location.pathname); }
  return <main><header className="site-header"><div className="container nav-inner"><a href="#inicio" className="brand-lockup"><img src={LOGO} alt="C7 Store" /><span>C7 <b>STORE</b></span></a><nav><a href="#catalogo">Catálogo</a><a href="#diferenciais">Por que a C7</a><a href={INSTAGRAM} target="_blank" rel="noreferrer">Instagram <ArrowUpRight size={13} /></a></nav><a className="nav-contact" href={WHATSAPP} target="_blank" rel="noreferrer"><MessageCircle size={16} /> Falar com a C7</a></div></header><section className="hero" id="inicio"><div className="hero-orbit orbit-one" /><div className="hero-orbit orbit-two" /><div className="container hero-grid"><div className="hero-copy"><div className="hero-label"><span /> Tecnologia seminova, revisada e pronta</div><h1>Seu próximo<br /><em>computador</em> está aqui.</h1><p>Notebooks e desktops seminovos revisados, com configuração transparente e atendimento de verdade. Escolha seu próximo equipamento com a C7 Store.</p><div className="hero-actions"><a href="#catalogo" className="primary-button">Explorar catálogo <ArrowUpRight size={17} /></a><button type="button" className="ghost-button advisor-hero-button" onClick={() => { trackEvent("advisor_open"); setShowAdvisor(true); }}><Bot size={17} /> Encontrar meu computador</button><a href={WHATSAPP} target="_blank" rel="noreferrer" className="ghost-button"><MessageCircle size={17} /> Atendimento</a></div><div className="hero-proof"><div className="proof-avatars"><span>c7</span><span>+</span></div><div><strong>Atendimento próximo</strong><small>Fale com quem entende de tecnologia</small></div></div></div><div className="hero-showcase"><div className="showcase-card back-card"><div className="showcase-topline"><span>ESTAÇÃO C7</span><span>01 / 03</span></div><div className="showcase-device device-back"><Monitor size={138} strokeWidth={0.65} /></div></div><div className="showcase-card front-card"><div className="showcase-topline"><span>CURADORIA C7</span><span className="live-dot">● SEMINOVO REVISADO</span></div><div className="showcase-device"><Laptop size={198} strokeWidth={0.65} /><div className="screen-shine" /></div><div className="showcase-caption"><span>Equipamentos selecionados</span><strong>prontos para você</strong></div></div><div className="floating-note"><ShieldCheck size={18} /><span><b>1 ano de garantia</b><small>Compra segura e configuração conferida</small></span></div></div></div></section>{activeCampaign && <CampaignSpotlight campaign={activeCampaign as PublicCampaign} onSelect={(product) => { setSelectedProduct(product); document.getElementById("catalogo")?.scrollIntoView({ behavior: "smooth" }); }} />}<section className="catalog-section" id="catalogo"><div className="container"><div className="section-heading"><div><div className="section-kicker">/ catálogo atualizado</div><h2>Escolha seu <em>próximo upgrade.</em></h2></div><p>{products.length} equipamentos<br />revisados e selecionados.</p></div><div className="catalog-toolbar"><div className="search-box"><Search size={18} /><input value={search} onChange={(event) => setSearch(event.target.value)} placeholder="Buscar por marca, modelo ou processador..." aria-label="Buscar produtos" /></div><div className="mobile-filter-actions"><button type="button" className={`mobile-filter-button ${showMobileFilters ? "is-active" : ""}`} onClick={() => setShowMobileFilters((value) => !value)} aria-expanded={showMobileFilters} aria-controls="catalog-filters"><SlidersHorizontal size={16} /><span>Filtros</span>{(brand !== "Todas" || ram !== "Todas" || category !== "Todos" || purpose !== "Todas" || minPrice !== "Todos" || sortBy !== "relevantes") && <b>{[brand !== "Todas", ram !== "Todas", category !== "Todos", purpose !== "Todas", minPrice !== "Todos", sortBy !== "relevantes"].filter(Boolean).length}</b>}</button><button type="button" className={`mobile-offer-button ${offersOnly ? "is-active" : ""}`} onClick={() => setOffersOnly((value) => !value)}><Sparkles size={15} /> <span>Ofertas</span></button></div><div id="catalog-filters" className={`filter-group ${showMobileFilters ? "is-open" : ""}`}><div className="mobile-filter-heading"><div><strong>Refinar resultados</strong><small>Escolha como deseja encontrar seu equipamento.</small></div><button type="button" onClick={() => setShowMobileFilters(false)} aria-label="Fechar filtros"><X size={17} /></button></div><SlidersHorizontal size={17} /><select value={brand} onChange={(event) => setBrand(event.target.value)} aria-label="Filtrar por marca">{brands.map((item) => <option key={item}>{item}</option>)}</select><select value={ram} onChange={(event) => setRam(event.target.value)} aria-label="Filtrar por memória">{ramOptions.map((item) => <option key={item}>{item === "Todas" ? "Toda RAM" : item}</option>)}</select><select value={category} onChange={(event) => setCategory(event.target.value)} aria-label="Filtrar por categoria"><option>Todos</option><option>Notebook</option><option>Desktop</option></select><select className="price-filter" value={minPrice} onChange={(event) => setMinPrice(event.target.value)} aria-label="Filtrar por faixa de preço"><option value="Todos">Qualquer preço</option><option value="ate-1500">Até R$ 1.500</option><option value="1500-2500">R$ 1.500 a R$ 2.500</option><option value="2500-4000">R$ 2.500 a R$ 4.000</option><option value="acima-4000">Acima de R$ 4.000</option></select><select className="purpose-filter" value={purpose} onChange={(event) => setPurpose(event.target.value)} aria-label="Filtrar por finalidade"><option value="Todas">Todas finalidades</option><option>Estudos</option><option>Trabalho</option><option>Jogos</option><option>Edição/criação</option><option>Uso básico</option></select><select className="sort-select" value={sortBy} onChange={(event) => setSortBy(event.target.value)} aria-label="Ordenar produtos"><option value="relevantes">Ordenar: relevantes</option><option value="menor-preco">Menor preço</option><option value="maior-preco">Maior preço</option><option value="ofertas">Ofertas primeiro</option></select><button className={`offer-filter ${offersOnly ? "active" : ""}`} onClick={() => setOffersOnly((value) => !value)}><Sparkles size={14} /> Ofertas</button></div></div><div className="results-line"><span><b>{filteredProducts.length}</b> resultados encontrados <small className="compare-hint"><GitCompareArrows size={12} /> Use “Comparar” nos cards para escolher até 3</small></span><div className="results-actions">{compareIds.length > 0 && <button className="compare-open-button" onClick={() => setShowCompare(true)}><GitCompareArrows size={14} /> Comparar selecionados ({compareIds.length})</button>}<div className="view-toggle" role="group" aria-label="Modo de visualização"><button type="button" className={viewMode === "cards" ? "is-active" : ""} onClick={() => setViewMode("cards")} aria-label="Visualização em cards" title="Visualização em cards"><LayoutGrid size={15} /> <span>Cards</span></button><button type="button" className={viewMode === "list" ? "is-active" : ""} onClick={() => setViewMode("list")} aria-label="Visualização em lista" title="Visualização em lista"><List size={15} /> <span>Lista</span></button></div>{(search || brand !== "Todas" || ram !== "Todas" || category !== "Todos" || purpose !== "Todas" || minPrice !== "Todos" || offersOnly || sortBy !== "relevantes") && <button onClick={clearFilters}>Limpar filtros <X size={14} /></button>}</div></div>{isLoading ? <div className="catalog-loading"><Loader2 className="spin" size={26} /> Carregando catálogo...</div> : filteredProducts.length > 0 ? <div className={`product-grid ${viewMode === "list" ? "is-list" : ""}`}>{filteredProducts.map((product) => <ProductCard key={product.id} product={product} onSelect={setSelectedProduct} comparing={compareIds.includes(product.id)} onCompare={toggleCompare} onShare={setSharingProduct} onTrack={trackEvent} />)}</div> : <div className="empty-state"><Search size={28} /><h3>Nenhum equipamento encontrado</h3><p>Tente buscar por outra marca, modelo ou configuração.</p></div>}</div></section><section className="trust-section" id="diferenciais"><div className="container trust-grid"><div className="trust-intro"><div className="section-kicker">/ do nosso jeito</div><h2>Comprar tecnologia pode ser <em>simples.</em></h2><p>Você recebe informação clara, curadoria cuidadosa e suporte para escolher o equipamento seminovo que realmente faz sentido para sua rotina.</p></div><div className="trust-items"><div className="trust-item"><span className="trust-icon"><Check size={18} /></span><div><strong>Condição informada com clareza</strong><p>Fotos, estado físico e configuração apresentados de forma transparente.</p></div></div><div className="trust-item"><span className="trust-icon"><PackageCheck size={18} /></span><div><strong>Equipamentos revisados</strong><p>Seleção feita com cuidado antes de chegar até o catálogo.</p></div></div><div className="trust-item warranty-trust-item"><span className="trust-icon"><ShieldCheck size={18} /></span><div><strong>1 ano de garantia</strong><p>Seu equipamento conta com a garantia C7 Store para você comprar com mais segurança.</p></div></div><div className="trust-item"><span className="trust-icon"><MessageCircle size={18} /></span><div><strong>Atendimento humano</strong><p>Converse com nossa equipe e tire dúvidas antes de decidir.</p></div></div></div></div></section><footer className="site-footer"><div className="container footer-main"><div className="footer-brand"><a href="#inicio" className="brand-lockup"><img src={LOGO} alt="C7 Store" /><span>C7 <b>STORE</b></span></a><p>Seu próximo equipamento,<br />do seu jeito.</p></div><div className="footer-contact"><span>Fale com a gente</span><a href={WHATSAPP} target="_blank" rel="noreferrer">(51) 3055-3090 <ArrowUpRight size={15} /></a><a href={INSTAGRAM} target="_blank" rel="noreferrer">@c7tec_store <Instagram size={15} /></a></div><div className="footer-cta"><span>Encontrou o seu?</span><a href={WHATSAPP} target="_blank" rel="noreferrer" className="primary-button">Chamar no WhatsApp <MessageCircle size={16} /></a></div></div><div className="container footer-bottom"><span>© 2026 C7 Store. Catálogo sujeito à disponibilidade.</span><span>Feito para escolher melhor.</span></div></footer>{selectedProduct && <DetailsModal product={selectedProduct} onClose={closeDetails} onTrack={trackEvent} />}{showCompare && <CompareModal products={comparingProducts} onClose={() => setShowCompare(false)} onSelect={setSelectedProduct} onRemove={(id) => { setCompareIds((current) => current.filter((item) => item !== id)); if (comparingProducts.length <= 1) setShowCompare(false); }} />}{sharingProduct && <ShareModal product={sharingProduct} onClose={() => setSharingProduct(null)} onTrack={trackEvent} />}{showAdvisor && <AdvisorModal products={products} onClose={() => setShowAdvisor(false)} onSelect={setSelectedProduct} onTrack={trackEvent} />}</main>;
}
